                                                                                WITH customer_stock_date AS (SELECT MAX(i.month_date) AS month_date FROM agents_scm_inventory_sku_data_d AS i WHERE (i.warehouse_classify IN ('01', '02', '20') AND (i.warehouse_classify <> '20' OR NOT i.warehouseid IN ('N436', 'Y204')))), customer_stock AS (SELECT i.warehouseid AS warehouseid, i.warehouse_name AS warehouse_name, i.belong_base AS belong_base, i.material_code AS sku, i.available_qty AS available_qty, i.prod_date AS prod_date, i.sap_warehouseid AS sap_warehouseid, i.plant AS plant, i.quality_batch AS quality_batch, i.is_good_prod AS is_good_prod, i.warehouse_classify AS warehouse_classify FROM agents_scm_inventory_sku_data_d AS i INNER JOIN customer_stock_date AS s ON i.month_date = s.month_date WHERE (i.warehouse_classify = '20' AND NOT i.warehouseid IN ('N436', 'Y204'))), customer_warehouses AS (SELECT i.warehouseid AS warehouse_code, MAX(i.warehouse_name) AS warehouse_name, CASE WHEN COUNT(DISTINCT i.belong_base) = 1 THEN MAX(i.belong_base) END AS base FROM customer_stock AS i GROUP BY i.warehouseid), customer_execution_latest AS (SELECT e.executeorderno AS executeorderno, e.executeorderlineno AS executeorderlineno, MAX(e.load_time) AS load_time FROM agents_scm_execute_detail_d AS e INNER JOIN customer_warehouses AS w ON e.warehouseid = w.warehouse_code WHERE NOT NULLIF(TRIM(e.executeorderno), '') IS NULL AND NOT e.executeorderlineno IS NULL GROUP BY e.executeorderno, e.executeorderlineno), customer_execution AS (SELECT DISTINCT e.executeorderno AS executeorderno, e.executeorderlineno AS executeorderlineno, e.warehouseid AS warehouseid, e.cust_order_no AS cust_order_no, e.cust_code AS cust_code, e.header_addtime AS header_addtime, e.requireddeliverytime AS requireddeliverytime, e.qtyordered AS qtyordered, e.qtyallocated AS qtyallocated, e.qtyshipped AS qtyshipped, e.bizunitconvertrate AS bizunitconvertrate, e.prapare_order_status AS prapare_order_status, e.bizflowstatus AS bizflowstatus, e.detailstatus AS detailstatus, e.order_close_time AS order_close_time, e.wms_close_time AS wms_close_time, e.canceltime AS canceltime, e.dmscanceltime AS dmscanceltime, e.order_type AS order_type, e.adjust_order_qty AS adjust_order_qty, e.pack_unitqty AS pack_unitqty, e.delivery_qty AS delivery_qty, e.organizationid AS organizationid, e.ownerid AS ownerid, e.material_code AS material_code, n.cust_name AS cust_name, COALESCE(t.material_name, n.material_name) AS material_name FROM agents_dwd_scm_execute_detail_mi AS e INNER JOIN customer_warehouses AS w ON e.warehouseid = w.warehouse_code LEFT JOIN (SELECT t.warehouseid AS warehouseid, t.material_code AS material_code, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_name) END AS warehouse_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.material_name) END AS material_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.live_qty) END AS live_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.available_qty) END AS available_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.pack_unit_qty) END AS pack_unit_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.freeze_qty) END AS freeze_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_transfer_qty) END AS warehouse_transfer_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_onway_qty) END AS transfer_onway_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_prepare_qty) END AS transfer_prepare_qty FROM agents_scm_warehouse_total_data_d AS t WHERE NOT NULLIF(TRIM(t.warehouseid), '') IS NULL AND NOT NULLIF(TRIM(t.material_code), '') IS NULL GROUP BY t.warehouseid, t.material_code) AS t ON t.warehouseid = e.warehouseid AND t.material_code = e.material_code LEFT JOIN (SELECT o.executeorderno AS executeorderno, o.executeorderlineno AS executeorderlineno, CASE WHEN COUNT(DISTINCT o.cust_name) = 1 THEN MAX(o.cust_name) END AS cust_name, CASE WHEN COUNT(DISTINCT o.material_name) = 1 THEN MAX(o.material_name) END AS material_name FROM agents_scm_execute_detail_d AS o GROUP BY o.executeorderno, o.executeorderlineno) AS n ON n.executeorderno = e.executeorderno AND n.executeorderlineno = e.executeorderlineno WHERE NULLIF(TRIM(e.executeorderno), '') IS NOT NULL AND e.executeorderlineno IS NOT NULL), customer_execution_keys AS (SELECT e.executeorderno AS executeorderno, e.executeorderlineno AS executeorderlineno, COUNT(*) AS versions, e.organizationid AS organizationid, e.ownerid AS ownerid FROM customer_execution AS e GROUP BY e.executeorderno, e.executeorderlineno, e.organizationid, e.ownerid), customer_valid_lines AS (SELECT w.warehouse_code AS warehouse_code, w.warehouse_name AS warehouse_name, w.base AS base, e.cust_order_no AS order_no, e.cust_code AS customer_code, e.cust_name AS customer_name, e.material_code AS sku, e.material_name AS material_name, e.header_addtime AS created_at, e.requireddeliverytime AS requested_at, e.bizflowstatus AS order_status, e.qtyordered / e.bizunitconvertrate AS ordered, e.adjust_order_qty AS demand, e.pack_unitqty AS allocated, e.delivery_qty AS shipped, CASE WHEN e.qtyshipped < e.qtyordered THEN 1 ELSE 0 END AS unshipped FROM customer_execution AS e INNER JOIN customer_execution_keys AS k ON (e.executeorderno = k.executeorderno AND e.executeorderlineno = k.executeorderlineno) AND (COALESCE(e.organizationid, '') = COALESCE(k.organizationid, '') AND COALESCE(e.ownerid, '') = COALESCE(k.ownerid, '')) INNER JOIN customer_warehouses AS w ON e.warehouseid = w.warehouse_code WHERE (k.versions = 1 AND e.detailstatus = 10 AND e.order_close_time IS NULL AND e.wms_close_time IS NULL AND NULLIF(TRIM(e.canceltime), '') IS NULL AND NULLIF(TRIM(CAST(e.dmscanceltime AS VARCHAR)), '') IS NULL AND (e.prapare_order_status IS NULL OR NOT e.prapare_order_status IN ('作废', '已签收')) AND NOT NULLIF(TRIM(e.cust_order_no), '') IS NULL AND NOT NULLIF(TRIM(e.material_code), '') IS NULL AND e.bizunitconvertrate > 0 AND e.qtyordered >= 0 AND e.qtyallocated >= 0 AND e.qtyshipped >= 0 AND (e.order_type IS NULL OR NOT e.order_type IN ('ZUB', 'ZO14', 'TT', 'TT1', 'TT2', 'STO'))) AND (e.adjust_order_qty >= 0 AND e.pack_unitqty >= 0 AND e.delivery_qty >= 0)), customer_open_orders AS (SELECT l.warehouse_code AS warehouse_code, l.order_no AS order_no, l.customer_code AS customer_code FROM customer_valid_lines AS l GROUP BY l.warehouse_code, l.order_no, l.customer_code HAVING MAX(l.unshipped) = 1), customer_open_lines AS (SELECT l.warehouse_code AS warehouse_code, l.warehouse_name AS warehouse_name, l.base AS base, l.order_no AS order_no, l.customer_code AS customer_code, CASE WHEN COUNT(DISTINCT l.customer_name) = 1 THEN MAX(l.customer_name) END AS customer_name, l.sku AS sku, CASE WHEN COUNT(DISTINCT l.material_name) = 1 THEN MAX(l.material_name) END AS material_name, MIN(l.created_at) AS created_at, MIN(l.requested_at) AS requested_at, CASE WHEN COUNT(DISTINCT l.order_status) = 1 THEN MAX(l.order_status) END AS order_status, SUM(l.ordered) AS ordered, SUM(l.demand) AS demand, SUM(l.allocated) AS allocated, SUM(l.shipped) AS shipped, CASE WHEN SUM(l.demand) > SUM(l.allocated) THEN SUM(l.demand) - SUM(l.allocated) ELSE 0 END AS remaining FROM customer_valid_lines AS l INNER JOIN customer_open_orders AS o ON l.warehouse_code = o.warehouse_code AND l.order_no = o.order_no AND (l.customer_code = o.customer_code OR (l.customer_code IS NULL AND o.customer_code IS NULL)) GROUP BY l.warehouse_code, l.warehouse_name, l.base, l.order_no, l.customer_code, l.sku), customer_sku_demand AS (SELECT l.warehouse_code AS warehouse_code, l.sku AS sku, MAX(l.material_name) AS material_name, SUM(l.demand) AS demand, SUM(l.allocated) AS allocated, SUM(l.remaining) AS remaining FROM customer_open_lines AS l GROUP BY l.warehouse_code, l.sku), customer_stock_batches AS (SELECT i.warehouseid AS warehouse_code, i.sku AS sku, CASE WHEN COUNT(i.available_qty) = COUNT(*) AND (COUNT(*) = 1 OR (MIN(i.available_qty) = 0 AND MAX(i.available_qty) = 0)) THEN SUM(i.available_qty) END AS available FROM customer_stock AS i GROUP BY i.warehouseid, i.sku, i.prod_date, i.sap_warehouseid, i.plant, i.quality_batch, i.is_good_prod, i.warehouse_classify), customer_sku_stock AS (SELECT t.warehouseid AS warehouse_code, t.material_code AS sku, t.available_qty AS available FROM (SELECT t.warehouseid AS warehouseid, t.material_code AS material_code, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_name) END AS warehouse_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.material_name) END AS material_name, CASE WHEN COUNT(*) = 1 THEN MAX(t.live_qty) END AS live_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.available_qty) END AS available_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.pack_unit_qty) END AS pack_unit_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.freeze_qty) END AS freeze_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.warehouse_transfer_qty) END AS warehouse_transfer_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_onway_qty) END AS transfer_onway_qty, CASE WHEN COUNT(*) = 1 THEN MAX(t.transfer_prepare_qty) END AS transfer_prepare_qty FROM agents_scm_warehouse_total_data_d AS t WHERE NOT NULLIF(TRIM(t.warehouseid), '') IS NULL AND NOT NULLIF(TRIM(t.material_code), '') IS NULL GROUP BY t.warehouseid, t.material_code) AS t INNER JOIN customer_warehouses AS w ON w.warehouse_code = t.warehouseid), customer_prior AS (SELECT l.warehouse_code AS warehouse_code, l.order_no AS order_no, l.customer_code AS customer_code, l.sku AS sku, COALESCE(SUM(p.remaining), 0) AS prior_remaining FROM customer_open_lines AS l LEFT JOIN customer_open_lines AS p ON l.warehouse_code = p.warehouse_code AND l.sku = p.sku AND p.remaining > 0 AND (COALESCE(CAST(p.created_at AS VARCHAR), '') < COALESCE(CAST(l.created_at AS VARCHAR), '') OR (COALESCE(CAST(p.created_at AS VARCHAR), '') = COALESCE(CAST(l.created_at AS VARCHAR), '') AND p.order_no < l.order_no) OR (COALESCE(CAST(p.created_at AS VARCHAR), '') = COALESCE(CAST(l.created_at AS VARCHAR), '') AND p.order_no = l.order_no AND COALESCE(p.customer_code, '') < COALESCE(l.customer_code, ''))) WHERE l.remaining > 0 GROUP BY l.warehouse_code, l.order_no, l.customer_code, l.sku), customer_current_lines AS (SELECT l.warehouse_code AS warehouse_code, l.warehouse_name AS warehouse_name, l.base AS base, l.order_no AS order_no, l.customer_code AS customer_code, l.customer_name AS customer_name, l.sku AS sku, l.material_name AS material_name, l.created_at AS created_at, l.requested_at AS requested_at, l.order_status AS order_status, l.ordered AS ordered, l.demand AS demand, l.allocated AS allocated, l.shipped AS shipped, l.remaining AS remaining, CASE WHEN l.remaining = 0 THEN 0 WHEN i.sku IS NULL OR NOT i.available IS NULL THEN CASE WHEN COALESCE(i.available, 0) <= COALESCE(p.prior_remaining, 0) THEN l.remaining WHEN i.available >= COALESCE(p.prior_remaining, 0) + l.remaining THEN 0 ELSE l.remaining - i.available + COALESCE(p.prior_remaining, 0) END END AS shortage FROM customer_open_lines AS l LEFT JOIN customer_prior AS p ON l.warehouse_code = p.warehouse_code AND l.order_no = p.order_no AND l.sku = p.sku AND (l.customer_code = p.customer_code OR (l.customer_code IS NULL AND p.customer_code IS NULL)) LEFT JOIN customer_sku_stock AS i ON l.warehouse_code = i.warehouse_code AND l.sku = i.sku), customer_materials AS (SELECT m.material_code AS sku, CASE WHEN COUNT(DISTINCT m.product_categ_name) = 1 THEN MAX(m.product_categ_name) END AS category, CASE WHEN COUNT(DISTINCT m.material_group_name) = 1 THEN MAX(m.material_group_name) END AS material_group FROM agents_scm_material_in_out_summary_d AS m GROUP BY m.material_code), customer_source_presence AS (SELECT COUNT(*) AS source_count FROM (SELECT 1 AS present FROM agents_dwd_scm_execute_detail_mi AS e LIMIT 1) AS p), customer_current AS (SELECT CAST(CONCAT(SUBSTRING(s.month_date, 1, 4), '-', SUBSTRING(s.month_date, 5, 2), '-', SUBSTRING(s.month_date, 7, 2)) AS DATE) AS snapshot_date, '分仓' AS location_type, w.warehouse_code AS location_code, w.warehouse_name AS location_name, w.base AS base, w.warehouse_code AS warehouse_code, d.sku AS sku, d.material_name AS material_name, m.category AS category, m.material_group AS material_group, CASE WHEN p.source_count > 0 THEN COALESCE(d.demand, 0) END AS demand, CASE WHEN p.source_count > 0 THEN COALESCE(d.allocated, 0) END AS allocated, CASE WHEN p.source_count > 0 THEN COALESCE(d.remaining, 0) END AS remaining, CASE WHEN p.source_count > 0 AND (i.sku IS NULL OR NOT i.available IS NULL) THEN CASE WHEN COALESCE(i.available, 0) > 0 THEN i.available ELSE 0 END END AS available, CASE WHEN p.source_count > 0 AND (i.sku IS NULL OR NOT i.available IS NULL) THEN CASE WHEN COALESCE(d.remaining, 0) > CASE WHEN i.available > 0 THEN i.available ELSE 0 END THEN COALESCE(d.remaining, 0) - CASE WHEN i.available > 0 THEN i.available ELSE 0 END ELSE 0 END END AS shortage, CASE WHEN p.source_count = 0 OR s.month_date IS NULL OR (NOT i.sku IS NULL AND i.available IS NULL) THEN 1 ELSE 0 END AS invalid FROM customer_warehouses AS w CROSS JOIN customer_stock_date AS s CROSS JOIN customer_source_presence AS p LEFT JOIN customer_sku_demand AS d ON w.warehouse_code = d.warehouse_code LEFT JOIN customer_sku_stock AS i ON d.warehouse_code = i.warehouse_code AND d.sku = i.sku LEFT JOIN customer_materials AS m ON d.sku = m.sku) SELECT c.snapshot_date AS snapshot_date, c.location_type AS location_type, c.location_code AS location_code, c.location_name AS location_name, c.base AS base, c.warehouse_code AS warehouse_code, c.sku AS sku, c.material_name AS material_name, c.category AS category, c.material_group AS material_group, c.demand AS demand, c.allocated AS allocated, c.remaining AS remaining, c.available AS available, c.shortage AS shortage, c.invalid AS invalid FROM customer_current AS c
